def strings(language: str) -> dict[str, str]:
    index = 1 if language == "pl" else 0
    return {key: pair[index] for key, pair in STRINGS.items()}


def translate_text(text: str, language: str) -> str:
    if language != "en":
        return text
    exact = {"katalog DCC": "DCC catalog", "digest rejestru": "registry digest", "plik Compose": "Compose file", "rejestr": "registry"}
    if text in exact:
        return exact[text]
    for polish, english in sorted(DIAGNOSTICS.items(), key=lambda item: len(item[0]), reverse=True):
        text = text.replace(polish, english)
    return text


def localize_payload(value, language: str):
    if isinstance(value, list):
        return [localize_payload(item, language) for item in value]
    if isinstance(value, dict):
        return {
            key: translate_text(item, language) if key in {"message", "progress", "result", "error", "source", "auto_update_reason"} and isinstance(item, str)
            else localize_payload(item, language)
            for key, item in value.items()
        }
    return value
